service.method:
SELECT count(*) AS COUNT FROM (
SELECT DISTINCT CTGL.STATUS AS CONT_STATUS , CTGL.CONT_TYPE , CTGL.CATEGORY , CFGL.CONT_FORM_NAME , CTGL.CONT_FORM_NO , CTGL.CONT_SUBJECT , CTGL.CONT_FROM , CTGL.CONT_TO , CTGL.CONT_METHOD , CTGL.CONT_NO , CTGL.CONT_GL_SEQ , CTGL.ADD_DATE , CTGL.CONT_DATE , CTGL.CREATOR , CASE WHEN CTGL.STATUS != 'C' THEN #DB_OWNER#NVL(SIGN.SIGN_FLAG, CTGL.STATUS) ELSE CTGL.STATUS END AS SIGN_STATUS , CTGL.DATA_SOURCE , CTGL.INNER_MANAGER_NAME , CTGL.INNER_MANAGER_ID , CTGL.OUTER_COMPANY_NAME , CTGL.OUTER_COMPANY_CODE , CTGL.OUTER_MANAGER_NAME , CTGL.OUTER_MANAGER_ID , CTGL.CONT_AMT , CTGL.PUSH_SEND_DATE , CTGL.AP_STATUS , TO_CHAR(CTGL.AP_MESSAGE) AS AP_MESSAGE FROM SDCAM DCAM INNER JOIN SCTGL CTGL ON DCAM.HOUSE_CODE = CTGL.HOUSE_CODE AND DCAM.COMPANY_CODE = CTGL.COMPANY_CODE AND DCAM.CODE = CTGL.CONT_NO AND DCAM.SEQ = CTGL.CONT_GL_SEQ LEFT OUTER JOIN SCFGL CFGL ON CTGL.HOUSE_CODE = CFGL.HOUSE_CODE AND CTGL.CONT_FORM_NO = CFGL.CONT_FORM_NO LEFT OUTER JOIN SSIGN SIGN ON CTGL.HOUSE_CODE = SIGN.HOUSE_CODE AND CTGL.CONT_NO = SIGN.CONT_NO AND CTGL.CONT_GL_SEQ = SIGN.CONT_GL_SEQ AND DCAM.USER_ID = SIGN.SIGNER WHERE DCAM.HOUSE_CODE = ${session.HOUSE_CODE} AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE} AND ( ( DCAM.USER_ID = '*' AND DCAM.USER_GROUP_CODE = $S{session.DEPARTMENT} ) OR ( DCAM.USER_GROUP_CODE = '*' AND DCAM.USER_ID = ${session.ID} ) ) AND CTGL.STATUS IN ('G', 'A', 'C') AND #DB_OWNER#NVL(CTGL.DEL_FLAG, 'N') <> 'Y' AND CTGL.ADD_DATE >= $S{F_DATE_FROM} AND CTGL.ADD_DATE <= $S{F_DATE_TO} AND CTGL.CATEGORY IN ($INS{F_CONT_CATEGORY}) AND CTGL.CONT_SUBJECT like '%' || $S{F_KEYWORD} || '%'
AND $S{F_STATUS} = ( CASE WHEN CTGL.STATUS != 'C' THEN #DB_OWNER#NVL(SIGN.SIGN_FLAG, CTGL.STATUS) ELSE CTGL.STATUS END )
AND CTGL.CONT_DATE >= $S{F_CALENDAR_FROM} AND CTGL.CONT_DATE <= $S{F_CALENDAR_TO}
AND CTGL.CONT_FROM <= $S{F_CALENDAR_TO} AND CTGL.CONT_TO >= $S{F_CALENDAR_FROM}
AND CTGL.ADD_DATE >= $S{F_CALENDAR_FROM} AND CTGL.ADD_DATE <= $S{F_CALENDAR_TO}
) A
ORDER BY CTGL.CONT_NO DESC, CTGL.CONT_GL_SEQ DESC

SELECT count(*) AS COUNT FROM (
SELECT DISTINCT CTGL.HOUSE_CODE , CTGL.COMPANY_CODE , CTGL.CONT_NO , CASE WHEN CONT_GL_SEQ = (SELECT TO_CHAR(MAX(TO_NUMBER(CONT_GL_SEQ))) FROM SCTGL WHERE HOUSE_CODE = CTGL.HOUSE_CODE AND COMPANY_CODE = CTGL.COMPANY_CODE AND CONT_NO = CTGL.CONT_NO AND STATUS in ('A', 'X') )
THEN 'Y' ELSE 'N' END AS CONT_GL_LAST , CTGL.CONT_GL_SEQ , CTGL.CATEGORY , CTGL.CONT_FORM_NO , CFGL.CONT_FORM_NAME , CTGL.STATUS AS CONT_STATUS , CTGL.STATUS AS MANUAL_STATUS , CTGL.CONT_SUBJECT , CTGL.CONT_FROM , CTGL.CONT_TO , CTGL.ADD_DATE , CTGL.CONT_DATE , CTGL.CONT_TYPE , CTGL.CONT_METHOD , CTGL.EXPIRED_ALARM , CTGL.CREATOR , CTGL.DATA_SOURCE , CTGL.INNER_MANAGER_NAME , CTGL.INNER_MANAGER_ID , CTGL.OUTER_COMPANY_NAME , CTGL.OUTER_COMPANY_CODE , CTGL.OUTER_MANAGER_NAME , CTGL.OUTER_MANAGER_ID , CTGL.CONT_AMT , CTGL.PUSH_SEND_DATE , CTGL.AP_STATUS , TO_CHAR(CTGL.AP_MESSAGE) AS AP_MESSAGE
, CASE WHEN CTGL.STATUS = 'T' THEN 0 ELSE 1 END
, CASE WHEN CTGL.CONT_TO <= ${EXPIRED_ALARM_TO} AND CTGL.CONT_TO >= ${EXPIRED_ALARM_FROM} THEN 'Y' ELSE 'N' END AS EXPIRED_ALARM_TARGET , CTGL.T_ID , CTGL.T_NAME , CTGL.T_IP , CTGL.T_MESSAGE
, '' AS EXPIRED_ALARM_TARGET
FROM SDCAM DCAM INNER JOIN SCTGL CTGL ON DCAM.HOUSE_CODE = CTGL.HOUSE_CODE AND DCAM.COMPANY_CODE = CTGL.COMPANY_CODE AND DCAM.CODE = CTGL.CONT_NO AND DCAM.SEQ = CTGL.CONT_GL_SEQ LEFT OUTER JOIN SCFGL CFGL ON CTGL.HOUSE_CODE = CFGL.HOUSE_CODE AND CTGL.CONT_FORM_NO = CFGL.CONT_FORM_NO WHERE DCAM.HOUSE_CODE = ${session.HOUSE_CODE} AND DCAM.USER_COMPANY_CODE = ${session.COMPANY_CODE}
AND ( ( DCAM.USER_ID = '*' AND DCAM.USER_GROUP_CODE = $S{session.DEPARTMENT} ) OR ( DCAM.USER_GROUP_CODE = '*' AND DCAM.USER_ID = ${session.ID} ) )
AND #DB_OWNER#NVL(CTGL.DEL_FLAG, 'N') = 'N' AND CTGL.CONT_NO = $S{CONT_NO} AND CTGL.CONT_GL_SEQ = $S{CONT_GL_SEQ} AND CTGL.CONT_TYPE = ${CONT_TYPE} AND CTGL.STATUS #MODE_TYPE_OPERATOR# ($INS{MODE_TYPE_STATUS}) AND CTGL.CATEGORY IN ($INS{F_CONT_CATEGORY}) AND CFGL.CONT_FORM_NO = $S{F_CONT_FORM_NO} AND ( 1=1 AND CTGL.CONT_SUBJECT like '%' || $S{F_KEYWORD} || '%' OR CTGL.CONT_NO like '%' || $S{F_KEYWORD} || '%' ) AND #DB_OWNER#NVL(CTGL.CONT_METHOD, 'X') #MANUAL_FLAG_OPERATOR# $S{MANUAL_FLAG_VALUE}
AND CASE WHEN CONT_GL_SEQ = (SELECT TO_CHAR(MAX(TO_NUMBER(CONT_GL_SEQ))) FROM SCTGL WHERE HOUSE_CODE = CTGL.HOUSE_CODE AND COMPANY_CODE = CTGL.COMPANY_CODE AND CONT_NO = CTGL.CONT_NO AND STATUS in ('A', 'X') ) THEN 'Y' ELSE 'N' END = 'Y'
AND CASE WHEN CTGL.CONT_TO <= ${EXPIRED_ALARM_TO} AND CTGL.CONT_TO >= ${EXPIRED_ALARM_FROM} THEN 'Y' ELSE 'N' END = 'Y'
AND CTGL.CONT_DATE >= $S{F_CALENDAR_FROM} AND CTGL.CONT_DATE <= $S{F_CALENDAR_TO}
AND CTGL.CONT_FROM <= $S{F_CALENDAR_TO} AND CTGL.CONT_TO >= $S{F_CALENDAR_FROM}
AND CTGL.ADD_DATE >= $S{F_CALENDAR_FROM} AND CTGL.ADD_DATE <= $S{F_CALENDAR_TO}
) A
ORDER BY CASE WHEN CTGL.STATUS = 'T' THEN 0 ELSE 1 END , #ORDER_COLUMN# #ORDER_SORT#


        INSERT INTO SMCWT
        (
			  HOUSE_CODE
			, COMPANY_CODE
			, DOC_NUMBER
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
			, CHANGE_USER_ID
			, DATA
		) VALUES (
			  ${session.HOUSE_CODE  }
			, ${session.COMPANY_CODE}
			, ${DOC_NUMBER          }
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, ${DATA				}
		)


UPDATE SMCWT SET
      CHANGE_DATE           = ${current.DATE}
    , CHANGE_TIME           = ${current.TIME}
    , CHANGE_USER_ID        = ${session.ID}
    , POSTPROCESSED         = ${POSTPROCESSED}
    , POSTPROCESSED_RESULT  = ${POSTPROCESSED_RESULT}
WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
  AND COMPANY_CODE      = ${session.COMPANY_CODE}
  AND DOC_NUMBER        = ${DOC_NUMBER}


UPDATE SMCWT SET
      CHANGE_DATE       = ${current.DATE}
    , CHANGE_TIME       = ${current.TIME}
    , CHANGE_USER_ID    = ${session.ID}
    , POSTPROCESSED     = 'P'
WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
  AND COMPANY_CODE      = ${session.COMPANY_CODE}
  AND POSTPROCESSED     = ${POSTPROCESSED}


        INSERT INTO SBUPR
        (
			  HOUSE_CODE
			, BIZ_CODE
			, BIZ_CATEGORY
			, BIZ_TYPE
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
			, CHANGE_USER_ID
			, DEL_FLAG
			, SELLER_NAME_LOC
			, IRS_NO
			, ZIP_CODE
			, ADDRESS_LOC
			, PHONE_NO
			, EMAIL
			, CEO_NAME_LOC
			, FOUNDATION_DATE
			, IF_FLAG

		) VALUES (
			  ${session.HOUSE_CODE  }
			, ${BIZ_CODE			}
			, ${BIZ_CATEGORY		}
			, ${BIZ_TYPE			}
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, 'N'
			, ${SELLER_NAME_LOC     }
			, ${IRS_NO			    }
			, ${ZIP_CODE		    }
			, ${ADDRESS_LOC		    }
			, ${PHONE_NO		    }
			, ${EMAIL			    }
			, ${CEO_NAME_LOC	    }
			, ${FOUNDATION_DATE	    }
			, 'N'
		)


        INSERT INTO SBUPI
        (
			  HOUSE_CODE
			, BIZ_CODE
			, SEQ
			, USER_ID
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
			, CHANGE_USER_ID
			, DEL_FLAG
			, USER_NAME
			, EMAIL
			, PHONE_NO
			, IF_FLAG

		) VALUES (
			  ${session.HOUSE_CODE  }
			, ${BIZ_CODE			}
			, ${SEQ					}
			, UPPER(${USER_ID}		)
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, 'N'
			, ${USER_NAME    		}
			, ${EMAIL			    }
			, ${PHONE_NO		    }
			, 'N'
		)


SELECT USER_ID
     , COMPANY_CODE
FROM SUSMT
WHERE HOUSE_CODE    = ${session.HOUSE_CODE}
  AND COMPANY_CODE  = ${session.COMPANY_CODE}
  AND WORK_TYPE     = 'Z'
